const COVER = ["p1", "p2", "p3", "p4", "p5", "p6", "p7", "p8", "p9", "p10"];

const esc = (s) =>
  String(s).replace(
    /[&<>"']/g,
    (c) =>
      ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[
        c
      ],
  );
const roman = (n) => {
  const map = [
    [10, "X"],
    [9, "IX"],
    [5, "V"],
    [4, "IV"],
    [1, "I"],
  ];
  let out = "";
  for (const [v, r] of map)
    while (n >= v) {
      out += r;
      n -= v;
    }
  return out;
};

const orn = `<svg class="orn" viewBox="0 0 180 22" fill="none" stroke="currentColor" stroke-width="1.1" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">
  <path d="M2 12h56M122 12h56" opacity=".6"/>
  <g><path d="M60 12c7 0 9-7 17-7-5 3-5 8 1 10-6 1-8-3-18-3z"/><path d="M70 14c3 3 7 3 10 1"/></g>
  <g transform="translate(180 0) scale(-1 1)"><path d="M60 12c7 0 9-7 17-7-5 3-5 8 1 10-6 1-8-3-18-3z"/><path d="M70 14c3 3 7 3 10 1"/></g>
  <path d="M90 3c-5 4-5 12 0 16 5-4 5-12 0-16z"/><path d="M90 7v10"/>
</svg>`;
const rings = `<i class="ring" style="top:27%"></i><i class="ring" style="top:67%"></i>`;

const section = (s) => `
<section class="sec">
  <div class="body ${s.side === "left" ? "pic-left" : ""}">
    <div class="txt">
      <h2>${esc(s.title)}</h2>
      ${orn}
      ${s.sub ? `<p class="sub">${esc(s.sub)}</p>` : ""}
      <ul class="items">
        ${s.items.map((it) => `
          <li>
            <span class="name">${esc(it.name)}</span>
            <span class="price">${Number(it.price)}${esc(SHOP.currency)}</span>
          </li>`).join("")}
      </ul>
    </div>
    ${s.img ? `<img class="pic" src="${IMG[s.img]}" alt="${esc(s.title)}">` : ""}
  </div>
</section>
`;

const leaves = [];
leaves.push({
  title: "Couverture",
  html: `<div class="sheet wood"><div class="panes">
    ${COVER.slice(0, 4)
      .map((k) => `<img class="t" src="${IMG[k]}" alt="">`)
      .join("")}
    <div class="brand">${esc(SHOP.name)}</div>
    ${COVER.slice(4)
      .map((k) => `<img class="m" src="${IMG[k]}" alt="">`)
      .join("")}
  </div></div>${rings}`,
});
PAGES.forEach((p, n) =>
  leaves.push({
    title: p.title,
    html: `<div class="sheet"><div class="inner">${p.sections.map(section).join("")}</div></div>${rings}`,
  }),
);

const book = document.getElementById("book");
const pips = document.getElementById("pips");
const label = document.getElementById("label");
const prev = document.getElementById("prev");
const next = document.getElementById("next");
const total = leaves.length - 1;
const reduce = window.matchMedia("(prefers-reduced-motion: reduce)").matches;

book.insertAdjacentHTML(
  "beforeend",
  leaves
    .map(
      (l, i) =>
        `<div class="leaf" data-i="${i}" role="group" aria-roledescription="page" aria-label="${esc(l.title)}">${l.html}</div>`,
    )
    .join(""),
);
pips.innerHTML = leaves
  .map(
    (l, i) =>
      `<button class="pip" type="button" data-go="${i}" aria-label="${esc(l.title)}"></button>`,
  )
  .join("");

const els = [...book.querySelectorAll(".leaf")];
const pipEls = [...pips.children];
let cur = -1;

function setCur(i) {
  if (i === cur) return;
  cur = i;
  label.textContent = i
    ? `${roman(i)} / ${roman(total)} · ${leaves[i].title}`
    : "Lamandine · Glissez pour ouvrir";
  pipEls.forEach((p, k) =>
    p.setAttribute("aria-current", k === i ? "true" : "false"),
  );
  prev.disabled = i === 0;
  next.disabled = i === total;
}

function go(i) {
  i = Math.max(0, Math.min(total, i));
  const l = els[i];
  const left = l.offsetLeft - (book.clientWidth - l.offsetWidth) / 2;
  book.scrollTo({ left, behavior: reduce ? "auto" : "smooth" });
}

let ticking = false;
function frame() {
  ticking = false;
  const mid = book.scrollLeft + book.clientWidth / 2;
  let best = 0,
    bestD = Infinity;
  els.forEach((l, i) => {
    const d = (l.offsetLeft + l.offsetWidth / 2 - mid) / l.offsetWidth;
    const ad = Math.abs(d);
    if (ad < bestD) {
      bestD = ad;
      best = i;
    }
    if (!reduce) {
      const c = Math.max(-1.3, Math.min(1.3, d));
      l.style.transform = `rotateY(${(-c * 22).toFixed(2)}deg) scale(${(1 - Math.min(ad, 1) * 0.06).toFixed(3)})`;
      l.style.setProperty("--dim", (Math.min(ad, 1) * 0.3).toFixed(3));
    }
  });
  setCur(best);
}
book.addEventListener(
  "scroll",
  () => {
    if (!ticking) {
      ticking = true;
      requestAnimationFrame(frame);
    }
  },
  { passive: true },
);
window.addEventListener("resize", frame);
if (document.fonts && document.fonts.ready) document.fonts.ready.then(frame);

document.addEventListener("click", (e) => {
  const b = e.target.closest("[data-go]");
  if (b) {
    go(Number(b.dataset.go));
    return;
  }
  const leaf = e.target.closest(".leaf");
  if (leaf && Number(leaf.dataset.i) !== cur) go(Number(leaf.dataset.i));
});
prev.addEventListener("click", () => go(cur - 1));
next.addEventListener("click", () => go(cur + 1));
document.addEventListener("keydown", (e) => {
  if (e.key === "ArrowRight") {
    e.preventDefault();
    go(cur + 1);
  }
  if (e.key === "ArrowLeft") {
    e.preventDefault();
    go(cur - 1);
  }
});

/* mouse drag, so desktop visitors can swipe too */
let drag = null,
  justDragged = false;
book.addEventListener("pointerdown", (e) => {
  if (e.pointerType !== "mouse" || e.button !== 0) return;
  drag = { x: e.clientX, s: book.scrollLeft, moved: false };
});
window.addEventListener("pointermove", (e) => {
  if (!drag) return;
  const dx = e.clientX - drag.x;
  if (!drag.moved && Math.abs(dx) > 5) {
    drag.moved = true;
    book.classList.add("dragging");
  }
  if (drag.moved) book.scrollLeft = drag.s - dx;
});
window.addEventListener("pointerup", () => {
  if (!drag) return;
  const moved = drag.moved;
  drag = null;
  if (moved) {
    justDragged = true;
    setTimeout(() => {
      justDragged = false;
    }, 0);
    book.classList.remove("dragging");
    go(cur);
  }
});
book.addEventListener(
  "click",
  (e) => {
    if (justDragged) {
      e.stopPropagation();
      e.preventDefault();
    }
  },
  true,
);

frame();
